}

export class AllowListPolicy implements EntryPolicy {
  private readonly allowed: Set<string>;

  constructor(accountIds: readonly string[]) {
    if (
      !Array.isArray(accountIds) ||
      accountIds.some((id: unknown) => typeof id !== "string" || id.length === 0)
    ) {
      throw new TypeError("accountIds must contain non-empty strings");
    }
    this.allowed = new Set(accountIds);
  }

  canEnter(accountId: string): boolean {
    return typeof accountId === "string" && this.allowed.has(accountId);
  }
}

export class DocumentPane {
  private activeState = false;

  constructor(private readonly policy: EntryPolicy) {}

  get active(): any {
    return this.activeState;
  }

  activate(accountId: string): boolean {
    const allowed = this.policy.canEnter(accountId);
    if (allowed) {
      this.activeState = true;
    }
    return allowed;
  }
}

