import { AllowListPolicy, DocumentPane } from './solution';
import type { EntryPolicy } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function assertThrowsTypeError(action: () => unknown, message: string): void {
  try {
    action();
  } catch (error) {
    assert(error instanceof TypeError, `${message}: expected TypeError`);
    return;
  }
  throw new Error(`${message}: expected an exception`);
}

const identifiers = ['Forge', 'guest', 'Forge'];
const policy: EntryPolicy = new AllowListPolicy(identifiers);
identifiers[0] = 'changed';
identifiers.push('late');
assert(policy.canEnter('Forge') === true, 'constructor must copy identifiers');
assert(policy.canEnter('forge') === false, 'membership must be case-sensitive');
assert(policy.canEnter('guest') === true, 'listed identifier should be allowed');
assert(policy.canEnter('late') === false, 'later source mutations must be ignored');
assert(new AllowListPolicy([]).canEnter('anyone') === false, 'empty allow-list should deny everyone');

assertThrowsTypeError(() => new AllowListPolicy(['']), 'empty identifier');
assertThrowsTypeError(() => new AllowListPolicy(['ok', 3] as unknown as readonly string[]), 'non-string identifier');
assertThrowsTypeError(() => new AllowListPolicy(null as unknown as readonly string[]), 'non-array allow-list');

const calls: string[] = [];
const changingPolicy: EntryPolicy = {
  canEnter(accountId: string): boolean {
    calls.push(accountId);
    return accountId === 'allowed';
  },
};
const pane = new DocumentPane(changingPolicy);
assert(pane.active === false, 'pane should initially be inactive');
assert(pane.activate('allowed') === true, 'activate should return policy result');
assert(pane.active === true, 'allowed activation should activate pane');
assert(pane.activate('denied') === false, 'denied activation should return false');
assert(pane.active === false, 'denial should deactivate an active pane');
assert(calls.length === 2 && calls[0] === 'allowed' && calls[1] === 'denied', 'policy must be called for every attempt');

